import { createServerClient } from "@supabase/ssr";
import { NextResponse, type NextRequest } from "next/server";
import { getRequiredRole, getRoleDashboardPath } from "@/lib/auth/roles";

export async function proxy(request: NextRequest) {
  let response = NextResponse.next({ request });
  const supabase = createServerClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll: () => request.cookies.getAll(),
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value }) => request.cookies.set(name, value));
          response = NextResponse.next({ request });
          cookiesToSet.forEach(({ name, value, options }) => response.cookies.set(name, value, options));
        },
      },
    },
  );
  const { data: { user } } = await supabase.auth.getUser();
  const pathname = request.nextUrl.pathname;
  const redirectTo = (path: string) => {
    const redirectResponse = NextResponse.redirect(new URL(path, request.url));
    response.cookies.getAll().forEach((cookie) => redirectResponse.cookies.set(cookie));
    return redirectResponse;
  };

  if (!user) {
    if (pathname === "/admin/login") return redirectTo("/login");
    if (pathname === "/" || pathname === "/login") return response;
    if (getRequiredRole(pathname)) return redirectTo("/login");
    return response;
  }

  const { data: profile, error } = await supabase
    .from("profiles")
    .select("role, is_active")
    .eq("id", user.id)
    .single();
  const destination = !error && profile?.is_active ? getRoleDashboardPath(profile.role) : null;

  if (pathname === "/admin/login") {
    return redirectTo(destination ?? "/login");
  }

  if (pathname === "/" || pathname === "/login") {
    if (destination) return redirectTo(destination);
    return response;
  }

  const requiredRole = getRequiredRole(pathname);
  if (requiredRole) {
    if (!destination) return redirectTo("/login");
    if (requiredRole !== profile?.role) return redirectTo(destination);
  }

  return response;
}

export const config = { matcher: ["/((?!_next/static|_next/image|favicon.ico|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)"] };
